import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicInteger;

public class LazySettingsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    /** A supplier that counts its calls and does a little real work. */
    static String buildConfig(AtomicInteger calls) {
        calls.incrementAndGet();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 2000; i++) {
            sb.append(i % 10);
        }
        return "cfg-" + sb.length();
    }

    public static void main(String[] args) {
        try {
            AtomicInteger calls = new AtomicInteger(0);
            LazySettings lazy = new LazySettings(() -> buildConfig(calls));

            check("nothing is built before the first get", false, lazy.isInitialised());
            check("isInitialised did not trigger the supplier", 0, calls.get());
            check("first get returns the supplied value", "cfg-2000", lazy.get());
            check("isInitialised is true afterwards", true, lazy.isInitialised());
            check("a second get does not call the supplier again", 1, calls.get());
            check("a second get returns the same value", "cfg-2000", lazy.get());

            AtomicInteger raceCalls = new AtomicInteger(0);
            LazySettings shared = new LazySettings(() -> buildConfig(raceCalls));
            CountDownLatch gate = new CountDownLatch(1);
            final String[] seen = new String[6];
            Thread[] racers = new Thread[6];
            for (int i = 0; i < racers.length; i++) {
                final int slot = i;
                racers[i] = new Thread(() -> {
                    try {
                        gate.await();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                    seen[slot] = shared.get();
                });
                racers[i].start();
            }
            gate.countDown();
            for (Thread racer : racers) {
                racer.join();
            }

            check("six racing threads built the value exactly once", 1, raceCalls.get());
            boolean allSame = true;
            for (String s : seen) {
                if (s == null || !s.equals(seen[0])) {
                    allSame = false;
                }
            }
            check("every racing thread saw the same value", Boolean.TRUE, Boolean.valueOf(allSame));
        } catch (InterruptedException e) {
            System.out.println("FAIL  the test thread was interrupted -- " + e);
            failures++;
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
        System.exit(0);
    }
}

