import java.util.function.Supplier;

/**
 * TASK: Build a thread-safe lazy initialiser.
 *
 * A LazySettings wraps a Supplier that is expensive to run. The value must be
 * created the FIRST time get() is called and never again -- not even when six
 * threads call get() at the same instant. The supplier never returns null.
 *
 *   get()           creates the value on first use and returns it; every later
 *                   call returns the SAME object without touching the supplier.
 *   isInitialised() true once the value exists, false before that. It must NOT
 *                   create the value.
 *
 * Use the double-checked locking idiom:
 *   - keep the field VOLATILE so other threads see a finished value,
 *   - check it once without locking (the fast path),
 *   - if it is null, synchronize on a lock object and CHECK AGAIN inside the
 *     lock before calling the supplier.
 * Without the second check two threads that both saw null would both build a value.
 *
 * Example: new LazySettings(() -> "cfg").get() -> "cfg", and a second get()
 *          returns "cfg" without calling the supplier again.
 */
public class LazySettings {

    private final Supplier<String> factory;
    private final Object lock = new Object();
    private volatile String value;

    public LazySettings(Supplier<String> factory) {
        this.factory = factory;
    }

    public String get() {
        String local = value;
        if (local == null) {
            synchronized (lock) {
                local = value;
                if (local == null) {
                    local = factory.get();
                    value = local;
                }
            }
        }
        return local;
    }

    public boolean isInitialised() {
        return value != null;
    }
}
